function toggleNavDropdown(event, id) {
    event.preventDefault();
    event.stopPropagation();

    var dropdown = document.getElementById(id);
    var allDropdowns = document.getElementsByClassName('nav-dropdown');
    var isCurrentlyOpen = dropdown.classList.contains('show');

    // Close all dropdowns first
    for (var i = 0; i < allDropdowns.length; i++) {
        allDropdowns[i].classList.remove('show');
    }

    // Re-open if it wasn't open
    if (!isCurrentlyOpen && dropdown) {
        dropdown.classList.add('show');
    }
}

// Close dropdowns when clicking outside
document.addEventListener('click', function(e) {
    if (!e.target.closest('.nav-dropdown-wrapper')) {
        var dropdowns = document.getElementsByClassName('nav-dropdown');
        for (var i = 0; i < dropdowns.length; i++) {
            dropdowns[i].classList.remove('show');
        }
    }
});

// Toggle mobile language menu
function toggleMobileLangMenu() {
    var switcher = document.querySelector('.mobile-lang-switcher');
    if (switcher) {
        switcher.classList.toggle('open');
    }
}

// Switch language by setting cookie + localStorage and reloading
function switchLanguage(lang) {
    document.cookie = 'preferred_lang=' + lang + ';path=/;max-age=31536000;SameSite=Lax' + (location.protocol === 'https:' ? ';Secure' : '');
    try { localStorage.setItem('preferred_lang', lang); } catch(e) {}
    window.location.reload();
}

(function(){
    // Check if banner was dismissed
    try {
    if(!localStorage.getItem('hide_walkstreet_banner')){
        var banner = document.getElementById('walkstreet-banner');
        if(banner){
            banner.style.display = 'flex';
            // Delayed slide-up entrance
            setTimeout(function(){
                banner.classList.add('ws-show');
                document.body.classList.add('has-banner');
            }, 1200);

            // Close handler — slide out, then hide
            document.getElementById('walkstreet-close').addEventListener('click', function(e){
                e.preventDefault();
                banner.classList.remove('ws-show');
                document.body.classList.remove('has-banner');
                setTimeout(function(){ banner.style.display = 'none'; }, 400);
                localStorage.setItem('hide_walkstreet_banner', '1');
            });
        }
    }
    } catch(e) {}
})();

