document.addEventListener("DOMContentLoaded", function() {
    const input = document.getElementById('search-input');
    const placeholders = [
        "may the force be with you",
        "I'll be back",
        "to infinity and beyond",
        "keep calm and carry on",
        "elementary, my dear Watson",
        "here's looking at you, kid",
        "you can't handle the truth!",
        "I'll have what she's having",
        "life is like a box of chocolates",
        "Houston, we have a problem",
        "you talking to me?",
        "just keep swimming",
        "why so serious?",
        "I see dead people",
        "hasta la vista, baby",
        "go ahead, make my day",
        "there's no place like home",
        "I'm the king of the world!",
        "eternal sunshine of the spotless mind",
        "you had me at hello",
        "I'm gonna make him an offer he can't refuse",
        "you're gonna need a bigger boat",
        "my precious",
        "carpe diem. Seize the day, boys",
        "keep your friends close, but your enemies closer",
        "frankly, my dear, I don't give a damn",
        "here's Johnny!",
        "I love the smell of napalm in the morning"
    ];
    let currentText = '';
    let isDeleting = false;
    let charIndex = 0;
    let iteration = 0;
    let currentIndex = Math.floor(Math.random() * placeholders.length);

    function type() {
        const typingSpeed = isDeleting ? 20 : 20 + Math.random() * 10;
        const deleteSpeed = 10;


        if (isDeleting) {
            if (charIndex > 0) {
                currentText = placeholders[currentIndex].substring(0, charIndex - 1);
                charIndex--;
                input.placeholder = currentText;
                setTimeout(type, deleteSpeed);
            } else {
                isDeleting = false;
                currentIndex = Math.floor(Math.random() * placeholders.length);
                setTimeout(type, 500);
            }
        } else {
            if (charIndex < placeholders[currentIndex].length) {
                currentText = placeholders[currentIndex].substring(0, charIndex + 1);
                charIndex++;
                input.placeholder = currentText;
                setTimeout(type, typingSpeed);
            } else {
                isDeleting = true;
                const delaynext = 2000+(iteration*500);

                setTimeout(type, delaynext);
                iteration++;
            }
        }
    }

    type();
});

function openSupportChat(){
    try {
        if (typeof window.BrevoConversations === "function") {
            window.BrevoConversations("openChat", true);
            return;
        }
        if (!document.getElementById("brevo-convo-script")) {
            window.BrevoConversationsID = "64b5a57d072c447de967a09b";
            window.BrevoConversations = window.BrevoConversations || function(){
                (window.BrevoConversations.q = window.BrevoConversations.q || []).push(arguments);
            };
            var s = document.createElement("script");
            s.id = "brevo-convo-script";
            s.async = true;
            s.src = "https://conversations-widget.brevo.com/brevo-conversations.js";
            s.onload = function(){ setTimeout(function(){
                try { window.BrevoConversations("openChat", true); } catch(e) {}
            }, 800); };
            document.head.appendChild(s);
        } else {
            window.BrevoConversations("openChat", true);
        }
    } catch(e) {}
}
